(function(){try{var f1=document.createElement('link');f1.rel='stylesheet';f1.href='https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap';document.head.appendChild(f1);}catch(e){}var css="\n  :root{\n    --harbour:#173B5C;\n    --harbour-deep:#102B43;\n    --harbour-abyss:#0B1E30;\n    --atlantic:#B07D1A;\n    --sky:#FFB000;\n    --amber:#FFB000;\n    --amber-deep:#E59D00;\n    --paper:#FFFFFF;\n    --paper-hi:#F4F4F4;\n    --ink:#1D1D1D;\n    --mist:#ECECEC;\n    --white:#FFFFFF;\n\n    --line:rgba(23,42,58,.14);\n    --line-soft:rgba(23,42,58,.08);\n    --line-dark:rgba(255,255,255,.16);\n    --line-dark-soft:rgba(255,255,255,.08);\n\n    --font-display:\"Plus Jakarta Sans\",\"Avenir Next\",Avenir,\"Segoe UI\",sans-serif;\n    --font-body:\"Inter\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;\n\n    --wrap:1300px;\n    --gutter:clamp(1.25rem,5vw,4.5rem);\n    --radius:10px;\n\n    /* semantic tokens (theme-swappable) */\n    --surface-card:var(--white);\n    --text-body:var(--ink);\n    --text-strong:#1D1D1D;\n    --label:var(--atlantic);\n    --outline:var(--harbour);\n    --nav-bg:rgba(248,245,240,.88);\n  }\n\n  /* light theme only — the site does not follow the device's dark setting */\n  :root{color-scheme:light}\n\n  *{box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  @media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n\n  body{\n    margin:0;\n    background:var(--paper);\n    color:var(--ink);\n    font-family:var(--font-body);\n    font-size:18px;\n    line-height:1.6;\n    -webkit-font-smoothing:antialiased;\n    text-rendering:optimizeLegibility;\n  }\n  img{max-width:100%}\n\n  h1,h2,h3{font-family:var(--font-display);font-weight:800;line-height:1.03;letter-spacing:-.02em;text-wrap:balance;margin:0}\n  p{margin:0}\n  a{color:inherit}\n\n  .wrap{max-width:var(--wrap);margin-inline:auto;padding-inline:var(--gutter)}\n\n  /* focus ring */\n  a:focus-visible,button:focus-visible{outline:2px solid var(--amber);outline-offset:3px;border-radius:2px}\n\n  /* ---------- nav ---------- */\n  header.nav{\n    position:sticky;top:0;z-index:60;\n    background:rgba(11,30,48,0);border-bottom:1px solid transparent;\n    transition:background .3s ease,border-color .3s ease,backdrop-filter .3s ease;\n  }\n  header.nav.solid{background:rgba(11,30,48,.96);backdrop-filter:blur(8px);border-bottom-color:var(--line-dark-soft)}\n  .nav-in{display:flex;align-items:center;justify-content:space-between;gap:2rem;height:80px}\n  .brand{display:flex;align-items:center;gap:.85rem;text-decoration:none;color:var(--white);\n    font-family:var(--font-display);font-weight:800;letter-spacing:-.01em;font-size:1.3rem;transition:color .3s ease}\n  header.nav.solid .brand{color:var(--white)}\n  .brand .mark{width:48px;height:48px;flex:none;display:block}\n  .ai{color:var(--amber)}\n  /* inline top nav (all widths) */\n  .nav-links{display:flex;align-items:center;flex-wrap:wrap;justify-content:flex-end;gap:clamp(.8rem,2.2vw,2.1rem)}\n  .nav-links a{text-decoration:none;font-size:.9rem;font-weight:500;white-space:nowrap;\n    color:var(--white);transition:color .2s,opacity .2s}\n  .nav-links a:hover,.nav-links a.active{color:var(--white)}\n  .nav-links a.active{opacity:1}\n  header.nav.solid .nav-links a{color:var(--white);opacity:1}\n  header.nav.solid .nav-links a:hover,header.nav.solid .nav-links a.active{opacity:1;color:var(--white)}\n  @media(max-width:520px){.nav-links{gap:.6rem .85rem}.nav-links a{font-size:.8rem}}\n  /* skip link */\n  .skip-link{position:absolute;left:-9999px;top:0;z-index:200;background:var(--amber);color:var(--ink);\n    font-family:var(--font-body);font-weight:600;font-size:.85rem;padding:.7rem 1.1rem;border-radius:6px}\n  .skip-link:focus{left:1rem;top:1rem}\n  /* ---------- hero ---------- */\n  .hero{position:relative;isolation:isolate;overflow:hidden;\n    background:var(--harbour-abyss);color:var(--white);\n    min-height:clamp(26rem,80vh,56rem);display:flex;align-items:center;\n    margin-top:-80px;padding:calc(80px + clamp(2rem,5vw,4rem)) 0 clamp(3rem,7vw,6rem)}\n  .hero-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;z-index:0}\n  .hero-tint{position:absolute;inset:0;z-index:1;pointer-events:none;\n    background:linear-gradient(155deg,rgba(23,59,92,.34) 0%,rgba(16,43,67,.44) 55%,rgba(11,30,48,.62) 100%)}\n  .hero-scrim{position:absolute;inset:0;z-index:1;pointer-events:none;\n    background:linear-gradient(180deg,rgba(11,30,48,.5) 0%,rgba(11,30,48,.42) 46%,rgba(11,30,48,.92) 100%)}\n  .hero-content{position:relative;z-index:3;width:100%}\n  .hero h1{font-size:clamp(3rem,10vw,8.6rem);letter-spacing:-.045em;font-weight:800;line-height:.94;max-width:16ch}\n  .hero .lede{margin-top:1.6rem;font-size:clamp(1.15rem,2.2vw,1.6rem);line-height:1.5;color:var(--white);max-width:40ch}\n  /* mobile / small devices: the network video reads as noise at phone size, use a gradient instead */\n  @media(max-width:860px){\n    .hero-video,.hero-tint{display:none}\n    .hero{background:\n      radial-gradient(125% 90% at 12% -8%,rgba(46,111,149,.42),transparent 55%),\n      linear-gradient(160deg,var(--harbour) 0%,var(--harbour-deep) 55%,var(--harbour-abyss) 100%)}\n  }\n\n  /* ---------- hero follow-on bands (were the 3 hero scroll stages) ---------- */\n  .hero-band{position:relative;color:var(--white);overflow:hidden}\n  .band-focus{background:var(--paper);overflow:visible}\n  .band-focus::before{content:none}\n  .band-focus>.wrap{background:var(--harbour-deep);border-radius:22px;\n    padding:clamp(2.2rem,5vw,3.8rem);box-shadow:0 26px 60px -30px rgba(11,30,48,.55)}\n  .hero-band .wrap{position:relative;z-index:1}\n  .hero-band .big-line{font-family:var(--font-display);font-weight:800;letter-spacing:-.03em;line-height:1.04}\n  .band-focus .big-line{font-size:clamp(2rem,5.4vw,4.4rem);max-width:22ch}\n  .hero-band .actions{margin-top:2.4rem;display:flex;flex-wrap:wrap;gap:1rem}\n  .hero-band .partners{margin-top:1.5rem;color:var(--white);font-size:1.02rem;max-width:44ch}\n\n  /* metric strip */\n  .metrics{position:relative;z-index:2;margin-top:clamp(2rem,4vw,3rem);\n    border-top:1px solid var(--line-dark);display:grid;grid-template-columns:repeat(2,1fr);max-width:640px}\n  .metrics .m{padding:1.4rem clamp(1rem,3vw,2.2rem) 1.6rem 0;border-right:1px solid var(--line-dark-soft)}\n  .metrics .m:last-child{border-right:0}\n  .metrics .m .k{font-weight:600;font-size:.64rem;letter-spacing:.18em;text-transform:uppercase;color:var(--sky)}\n  .metrics .m .v{font-family:var(--font-display);font-weight:800;font-size:clamp(1.05rem,2.1vw,1.5rem);\n    letter-spacing:-.01em;margin-top:.7rem;color:var(--white)}\n  @media(max-width:860px){.metrics{grid-template-columns:1fr}\n    .metrics .m{border-right:0;border-top:1px solid var(--line-dark-soft);padding-right:0}\n    .metrics .m:first-child{border-top:0}}\n\n  /* ---------- section scaffold ---------- */\n  section{padding-block:clamp(2.75rem,5vw,4.5rem)}\n  /* amber divider on every section break */\n  main>section:not(.hero),footer{border-top:1px solid var(--amber);\n    border-image:linear-gradient(90deg,transparent,var(--amber),transparent) 1}\n  .sec-head{max-width:46rem}\n  .sec-head h2{font-size:clamp(2rem,4.6vw,3.3rem);margin-top:1.1rem;letter-spacing:-.025em}\n  .sec-head .say{margin-top:1.4rem;font-size:1.13rem;line-height:1.65;color:var(--ink);opacity:1;max-width:62ch}\n  .band-dark{background:var(--harbour-deep);color:var(--white)}\n  #runs{padding-block:clamp(2.5rem,4.5vw,4rem)}\n  .band-dark .sec-head .say{color:var(--white)}\n  .band-mist{background:var(--mist)}\n  #legislation{background:var(--paper-hi)}\n\n  /* ---------- editorial ghost wordmark ---------- */\n  .editorial{position:relative;overflow:hidden;background:var(--paper)}\n  .ghost{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);\n    width:clamp(20rem,46vw,40rem);height:auto;aspect-ratio:1;\n    color:var(--text-strong);opacity:.08;\n    pointer-events:none;user-select:none;z-index:0}\n  .editorial .wrap{position:relative;z-index:1}\n  .editorial .lead{max-width:34rem}\n  .editorial .lead h2{font-size:clamp(2.1rem,5vw,3.6rem);letter-spacing:-.03em;margin-top:1.2rem}\n  .editorial .lead p{margin-top:1.5rem;font-size:1.13rem;line-height:1.65;opacity:1;max-width:52ch}\n  .editorial .lead p + p{margin-top:1.1rem}\n\n  .conv{background:var(--paper-hi)}\n\n  /* ---------- who it's for: editorial statement list ---------- */\n  .who-list{margin-top:clamp(2.5rem,5vw,4rem);border-top:1px solid var(--line)}\n  .who-list .row{display:grid;grid-template-columns:minmax(0,9rem) 1fr;gap:clamp(1rem,4vw,3rem);\n    align-items:baseline;padding-block:clamp(1.5rem,3vw,2.3rem);border-bottom:1px solid var(--line)}\n  .who-list .row .k{font-weight:700;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;\n    color:var(--label);padding-top:.5rem}\n  .who-list .row h3{font-family:var(--font-display);font-weight:800;letter-spacing:-.02em;line-height:1.14;\n    font-size:clamp(1.3rem,2.4vw,1.9rem);color:var(--text-strong)}\n  @media(max-width:640px){.who-list .row{grid-template-columns:1fr;gap:.45rem}}\n  @media(prefers-reduced-motion:no-preference){\n    .js .who-list .row.r:nth-child(2){transition-delay:.07s}\n    .js .who-list .row.r:nth-child(3){transition-delay:.14s}\n    .js .who-list .row.r:nth-child(4){transition-delay:.21s}\n    .js .who-list .row.r:nth-child(5){transition-delay:.28s}\n    .js .who-list .row.r:nth-child(6){transition-delay:.35s}\n  }\n\n\n  /* ---------- legislation ---------- */\n  .legis{margin-top:3rem;display:grid;grid-template-columns:1fr 1fr;gap:clamp(1rem,2vw,1.5rem)}\n  .legis .col{padding:clamp(1.6rem,3vw,2.4rem);background:var(--harbour-deep);color:var(--white);\n    border-radius:18px;box-shadow:0 26px 60px -30px rgba(11,30,48,.55)}\n  .legis .col + .col{padding:clamp(1.6rem,3vw,2.4rem)}\n  .legis .col .tag{font-family:var(--font-display);font-weight:800;font-size:1.5rem;\n    letter-spacing:-.01em;color:var(--white)}\n  .legis .col p{margin-top:1rem;font-size:1.04rem;line-height:1.6;color:var(--white);max-width:44ch}\n  @media(max-width:640px){\n    .legis{grid-template-columns:1fr}\n    .legis .col{padding:clamp(1.6rem,5vw,2.2rem)}\n    .legis .col + .col{padding:clamp(1.6rem,5vw,2.2rem);border-left:0;border-top:0}\n  }\n\n  /* ---------- how it runs ---------- */\n  .facts{display:grid;grid-template-columns:1fr 1fr;\n    gap:clamp(1.6rem,3.5vw,2.6rem) clamp(2rem,5vw,4rem);\n    border-top:1px solid var(--line-dark);padding-top:clamp(2rem,4vw,2.8rem)}\n  .facts .item .l{display:block;font-weight:600;font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;color:var(--sky)}\n  .facts .item .v{display:block;margin-top:.55rem;font-family:var(--font-display);font-weight:800;\n    letter-spacing:-.01em;font-size:clamp(1.05rem,1.7vw,1.35rem);line-height:1.2;color:var(--white)}\n  @media(max-width:640px){.facts{grid-template-columns:1fr;gap:1.5rem}}\n\n  /* ---------- join ---------- */\n  .join{background:var(--paper-hi);position:relative;overflow:visible}\n  .join::before{content:none}\n  .join .join-in{background:var(--harbour-deep);color:var(--white);border-radius:22px;max-width:64rem;\n    padding:clamp(2.2rem,5vw,3.8rem);box-shadow:0 26px 60px -30px rgba(11,30,48,.55)}\n  .join-in{position:relative;z-index:2;max-width:48rem}\n  .join h2{font-size:clamp(2rem,4.8vw,3.4rem);letter-spacing:-.025em}\n  .join p{margin-top:1.4rem;font-size:1.15rem;line-height:1.6;color:var(--white);max-width:54ch}\n  .join .roles{margin-top:1.9rem;display:flex;flex-wrap:wrap;gap:.6rem}\n  .join .roles a{font-size:.85rem;font-weight:500;padding:.45rem .9rem;text-decoration:none;\n    border:1px solid var(--line-dark);border-radius:999px;color:var(--sky);\n    transition:border-color .2s,color .2s,background .2s}\n  .join .roles a:hover{border-color:var(--amber);color:var(--amber)}\n  .join .contact-line{margin-top:1.7rem;font-size:1.05rem;color:var(--white)}\n  .join .contact-line a{color:var(--amber);text-decoration:none;border-bottom:1px solid rgba(255,176,0,.4);transition:border-color .2s}\n  .join .contact-line a:hover{border-bottom-color:var(--amber)}\n  .join .actions{margin-top:2.3rem;display:flex;flex-wrap:wrap;gap:1rem}\n\n  /* ---------- footer ---------- */\n  footer{background:var(--harbour-abyss);color:var(--white);padding-block:4rem 3rem;font-size:.92rem}\n  .foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:2.5rem}\n  footer .brand{color:var(--white);margin-bottom:1rem}\n  footer .partners{max-width:34ch;line-height:1.6}\n  footer .partners strong{color:var(--white);font-weight:600}\n  .foot-col .foot-h{font-family:var(--font-body);font-weight:600;font-size:.66rem;letter-spacing:.15em;\n    text-transform:uppercase;color:var(--sky);margin:0 0 1rem}\n  .foot-col a{display:block;text-decoration:none;color:var(--white);padding:.35rem 0;transition:color .2s}\n  .foot-col a:hover{color:var(--white)}\n  .fine{font-size:.8rem;opacity:.55;margin-top:3rem;border-top:1px solid var(--line-dark-soft);padding-top:1.6rem;\n    display:flex;flex-wrap:wrap;gap:1rem;justify-content:space-between}\n  @media(max-width:820px){.foot-top{grid-template-columns:1fr 1fr;gap:2rem}}\n  @media(max-width:480px){.foot-top{grid-template-columns:1fr}}\n\n  /* ---------- aims bento ---------- */\n  .bento{margin-top:3.2rem;display:grid;grid-template-columns:1fr 1fr;gap:clamp(18px,2vw,28px)}\n  .bento .tile{position:relative;overflow:hidden;border-radius:var(--radius);border:0;\n    padding:1.6rem;display:flex;flex-direction:column;justify-content:flex-end;aspect-ratio:3/2;\n    box-shadow:0 18px 38px -12px rgba(11,30,48,.5),0 6px 14px -6px rgba(11,30,48,.38);\n    transition:transform .4s cubic-bezier(.16,1,.3,1),box-shadow .4s cubic-bezier(.16,1,.3,1)}\n  .bento .tile.in:hover,.bento .tile:hover{transform:translateY(-6px) scale(1.008);z-index:2;\n    box-shadow:0 32px 60px -20px rgba(11,30,48,.6),0 10px 20px -10px rgba(11,30,48,.42)}\n  .tile h3{font-family:var(--font-display);font-weight:800;letter-spacing:-.02em;\n    font-size:1.35rem;margin-top:.55rem;line-height:1.08}\n  .tile p{margin-top:.75rem;font-size:1rem;line-height:1.55;opacity:1;max-width:46ch}\n  .tile.big{grid-column:span 2;aspect-ratio:3/2;padding:2.3rem}\n  .tile.big h3{font-size:clamp(1.7rem,2.6vw,2.4rem)}\n  .tile.big p{font-size:1.06rem}\n  .tile.photo{color:#fff;background-image:var(--img);background-size:cover;\n    background-position:center;background-color:var(--harbour-deep);background-clip:padding-box}\n  .tile.photo::before{content:\"\";position:absolute;inset:0;\n    background:linear-gradient(180deg,rgba(11,30,48,.28),rgba(11,30,48,.9))}\n  .tile.photo>*{position:relative;z-index:1}\n  /* below desktop, tiles narrow enough that fixed 3:2 would clip copy: let them grow */\n  @media(max-width:860px){\n    .bento .tile,.bento .tile.big{aspect-ratio:auto;min-height:clamp(220px,50vw,300px)}\n  }\n  @media(max-width:560px){\n    .bento{grid-template-columns:1fr}\n    .tile.big{grid-column:auto}\n  }\n\n  /* ---------- responsive pass ---------- */\n  .brand span{white-space:nowrap}\n  /* phones: keep the nav on one line, tighten the frame, scale the hero */\n  @media(max-width:560px){\n    :root{--gutter:1rem}\n    .nav-in{height:68px;gap:.7rem}\n    .brand{font-size:1.05rem;gap:.6rem}\n    .brand .mark{width:36px;height:36px}\n    .hero h1{font-size:clamp(2.5rem,12vw,3.4rem)}\n    .hero .lede{font-size:1.05rem}\n    .sec-head .say,.editorial .lead p,.join p{font-size:1.04rem}\n  }\n  /* very small phones: mark only, so the nav never overflows */\n  @media(max-width:400px){\n    .brand span{display:none}\n  }\n\n  /* ---------- reveal (rest state visible) ---------- */\n  .r{opacity:1}\n  @media(prefers-reduced-motion:no-preference){\n    .js .r{opacity:0;transform:translateY(24px);transition:opacity .8s cubic-bezier(.23,1,.32,1),transform .8s cubic-bezier(.23,1,.32,1)}\n    .js .r.in{opacity:1;transform:none}\n  }\n  @media (prefers-reduced-motion:reduce){\n    header.nav,.brand,.bento .tile{transition-duration:1ms}\n    .bento .tile.in:hover,.bento .tile:hover{transform:none}\n  }\n\n  /* ---------- ghost wordmark drift ---------- */\n  @keyframes ghostDrift{from{transform:translate(-50%,-50%) translateX(5%)}to{transform:translate(-50%,-50%) translateX(-5%)}}\n  /* scroll-linked parallax (sovereignai scrollLinked) */\n  @supports (animation-timeline:view()){\n    @media (prefers-reduced-motion:no-preference){\n      .ghost{animation:ghostDrift linear both;animation-timeline:view();animation-range:cover}\n    }\n  }\n";var html="<a class=\"skip-link\" href=\"#what\">Skip to content</a>\n\n<header class=\"nav\" id=\"nav\">\n  <div class=\"wrap nav-in\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Creative Tech North, home\">\n      <svg class=\"mark\" viewBox=\"0 0 32 32\" fill=\"none\" aria-hidden=\"true\">\n        <circle cx=\"16\" cy=\"16\" r=\"11.9\" stroke=\"currentColor\" stroke-width=\"1.1\" opacity=\".5\"/>\n        <polygon points=\"16,9.3 21.8,12.7 21.8,19.3 16,22.7 10.2,19.3 10.2,12.7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/>\n        <polygon points=\"16,13.1 20.6,16 16,18.9 11.4,16\" fill=\"#FFB000\"/>\n      </svg>\n      <span>Cre<span class=\"ai\">a</span>t<span class=\"ai\">i</span>ve Tech North</span>\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a href=\"#what\">What it is</a>\n      <a href=\"#aims\">Our aims</a>\n      <a href=\"#who\">Who it&rsquo;s for</a>\n      <a href=\"#runs\">How it runs</a>\n      <a href=\"#join\">Get involved</a>\n    </nav>\n  </div>\n</header>\n\n<main id=\"top\">\n\n  <!-- HERO -->\n  <section class=\"hero\" id=\"hero\">\n    <video class=\"hero-video\" autoplay muted loop playsinline preload=\"metadata\" poster=\"https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/hero-poster.jpg\" aria-hidden=\"true\">\n      <source src=\"https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/hero.mp4\" type=\"video/mp4\">\n    </video>\n    <div class=\"hero-tint\" aria-hidden=\"true\"></div>\n    <div class=\"hero-scrim\" aria-hidden=\"true\"></div>\n    <div class=\"wrap hero-content r\">\n      <h1>Cre<span class=\"ai\">a</span>t<span class=\"ai\">i</span>ve Tech North</h1>\n      <p class=\"lede\">A quarterly meet-up for creative and media professionals working with technology across the North of England.</p>\n    </div>\n  </section>\n\n  <!-- AI FOCUS + PLACES (merged) -->\n  <section class=\"hero-band band-focus\">\n    <div class=\"wrap r\">\n      <p class=\"big-line\">AI is evolving faster than most teams can keep pace with, so each meet-up carries a strong focus on the subject.</p>\n      <div class=\"metrics\" aria-label=\"At a glance\">\n        <div class=\"m\"><div class=\"k\">Format</div><div class=\"v\">Quarterly sessions</div></div>\n        <div class=\"m\"><div class=\"k\">Focus</div><div class=\"v\">AI and creative technology</div></div>\n      </div>\n      <p class=\"partners\">In partnership with FourPointZero and Dream Lab.</p>\n    </div>\n  </section>\n\n  <!-- EDITORIAL / WHAT IT IS -->\n  <section id=\"what\" class=\"editorial\">\n    <div class=\"ghost\" aria-hidden=\"true\">NORTH</div>\n    <div class=\"wrap\">\n      <div class=\"lead r\">\n        <h2>The work is already happening up here.</h2>\n        <p>The latest tools, the approaches professionals are taking, and both current and forthcoming legislation all come up. Most of the useful knowledge sits with the people already doing the work, which is what these meet-ups are for.</p>\n        <p>Each session centres on a practical demonstration from a fellow industry professional and a showcase of work, with time to talk it through afterwards. You leave with something you can put into practice.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- AIMS (bento) -->\n  <section id=\"aims\" class=\"conv\">\n    <div class=\"wrap\">\n      <div class=\"sec-head r\">\n        <h2>Our five key objectives</h2>\n        <p class=\"say\">The North of England has a wealth of industry talent. Our aim is to showcase it and help it grow.</p>\n      </div>\n      <div class=\"bento\">\n        <article class=\"tile r photo big\" style=\"--img:url('https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/aim1.jpg')\">\n          <h3>Connect the region</h3>\n          <p>Studios, broadcasters, agencies, universities and technology partners across the North know each other far less well than they should. Getting the right people together, regularly, is the first job.</p>\n        </article>\n        <article class=\"tile r photo\" style=\"--img:url('https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/aim2.jpg')\">\n          <h3>Share what is working</h3>\n          <p>Real projects with real numbers, explained by the people who did the work. The parts that went badly are usually the most useful hour of the night.</p>\n        </article>\n        <article class=\"tile r photo\" style=\"--img:url('https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/aim3.jpg')\">\n          <h3>Open up opportunity</h3>\n          <p>Circulating funding routes, joint bids, partnerships and commercial openings so they reach the whole community rather than the same handful of names each time.</p>\n        </article>\n        <article class=\"tile r photo\" style=\"--img:url('https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/aim4.jpg')\">\n          <h3>Raise the region&rsquo;s profile</h3>\n          <p>The national conversation about creative technology still defaults to London. A visible Northern community changes who gets invited and who gets funded.</p>\n        </article>\n        <article class=\"tile r photo\" style=\"--img:url('https://cdn.jsdelivr.net/gh/makinsonmjttrt/ctn-web@main/assets/aim5.jpg')\">\n          <h3>Build a route in</h3>\n          <p>Making it easier for people early in their careers, and those moving across from adjacent disciplines, to find their way into this work and to the people already doing it.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <!-- WHO IT'S FOR -->\n  <section id=\"who\" class=\"band-mist\">\n    <div class=\"wrap\">\n      <div class=\"sec-head r\">\n        <h2>Every part of the industry, in one room.</h2>\n        <p class=\"say\">From creative technology professionals and producers to creatives, artists and AI content platforms. Everyone is welcome.</p>\n      </div>\n      <div class=\"who-list\">\n        <div class=\"row r\"><div class=\"k\">Technologists</div><h3>Creative technology professionals and the teams who support them</h3></div>\n        <div class=\"row r\"><div class=\"k\">Production</div><h3>Producers and production teams</h3></div>\n        <div class=\"row r\"><div class=\"k\">Creatives</div><h3>Creatives, designers and directors</h3></div>\n        <div class=\"row r\"><div class=\"k\">Artists</div><h3>Artists and makers</h3></div>\n        <div class=\"row r\"><div class=\"k\">Platforms</div><h3>AI content platforms</h3></div>\n        <div class=\"row r\"><div class=\"k\">Studios</div><h3>Studios, agencies and independents</h3></div>\n      </div>\n    </div>\n  </section>\n\n\n  <!-- LEGISLATION -->\n  <section id=\"legislation\" class=\"band-mist\">\n    <div class=\"wrap\">\n      <div class=\"sec-head r\">\n        <h2>Legislation is part of the conversation.</h2>\n        <p class=\"say\">The rules are being written while the work happens. We make room to compare notes on them, peer to peer, with no compliance lecture.</p>\n      </div>\n      <div class=\"legis r\">\n        <div class=\"col\">\n          <div class=\"tag\">EU</div>\n          <p>The AI Act is in force, phasing in since 2025, and its reach does not stop at the Channel. Any studio working with European audiences or clients is already inside it, from transparency and disclosure through to how general-purpose models are used.</p>\n        </div>\n        <div class=\"col\">\n          <div class=\"tag\">UK</div>\n          <p>No equivalent Act yet. A growth-focused bill has been signalled but is not law. That leaves creative teams making their own calls on provenance, disclosure and where the human sits, often ahead of the rulebook.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- HOW IT RUNS -->\n  <section id=\"runs\" class=\"band-dark\">\n    <div class=\"wrap\">\n      <div class=\"sec-head r\">\n        <h2>Independent and industry-led.</h2>\n        <p class=\"say\">A joint initiative between FourPointZero and Dream Lab. As the group grows, a steering group drawn from across the regional industry will set the direction and the themes.</p>\n      </div>\n      <div class=\"r\" style=\"margin-top:3.2rem;max-width:820px\">\n        <div class=\"facts\" aria-label=\"Terms of reference\">\n          <div class=\"item\"><span class=\"l\">Where</span><span class=\"v\">Greater Manchester and Liverpool, Yorkshire in time</span></div>\n          <div class=\"item\"><span class=\"l\">How often</span><span class=\"v\">Quarterly</span></div>\n          <div class=\"item\"><span class=\"l\">Cost</span><span class=\"v\">Free of charge</span></div>\n          <div class=\"item\"><span class=\"l\">Lead theme</span><span class=\"v\">AI in creative and media</span></div>\n          <div class=\"item\"><span class=\"l\">Status</span><span class=\"v\">Not-for-profit</span></div>\n          <div class=\"item\"><span class=\"l\">Review</span><span class=\"v\">After the first event, then yearly</span></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- JOIN -->\n  <section id=\"join\" class=\"join\">\n    <div class=\"wrap join-in\">\n      <h2 style=\"margin-top:1.1rem\">Dates for the first meet-up land in the next couple of weeks.</h2>\n      <p>Follow the page to hear first. If you would like to be a founding supporter, speak, or offer a venue, we would like to hear from you.</p>\n      <div class=\"roles\">\n        <a href=\"mailto:hello@creativetechnorth.org.uk?subject=Founding%20supporter\">Founding supporters</a>\n        <a href=\"mailto:hello@creativetechnorth.org.uk?subject=Speaking%20at%20Creative%20Tech%20North\">Speakers</a>\n        <a href=\"mailto:hello@creativetechnorth.org.uk?subject=Offering%20a%20venue\">Venues</a>\n        <a href=\"mailto:hello@creativetechnorth.org.uk?subject=Attending\">Attendees</a>\n      </div>\n      <p class=\"contact-line\">Or just say hello: <a href=\"mailto:hello@creativetechnorth.org.uk\">hello@creativetechnorth.org.uk</a></p>\n    </div>\n  </section>\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <div class=\"foot-top\">\n      <div>\n        <a class=\"brand\" href=\"#top\">\n          <svg class=\"mark\" viewBox=\"0 0 32 32\" fill=\"none\" aria-hidden=\"true\">\n            <circle cx=\"16\" cy=\"16\" r=\"11.9\" stroke=\"currentColor\" stroke-width=\"1.1\" opacity=\".5\"/>\n            <polygon points=\"16,9.3 21.8,12.7 21.8,19.3 16,22.7 10.2,19.3 10.2,12.7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/>\n            <polygon points=\"16,13.1 20.6,16 16,18.9 11.4,16\" fill=\"#FFB000\"/>\n          </svg>\n          <span>Cre<span class=\"ai\">a</span>t<span class=\"ai\">i</span>ve Tech North</span>\n        </a>\n        <p class=\"partners\">A joint initiative between <strong>FourPointZero</strong> and <strong>Dream Lab</strong>.</p>\n      </div>\n      <div class=\"foot-col\">\n        <p class=\"foot-h\">Explore</p>\n        <a href=\"#what\">What it is</a>\n        <a href=\"#aims\">Our aims</a>\n        <a href=\"#who\">Who it's for</a>\n        <a href=\"#runs\">How it runs</a>\n      </div>\n      <div class=\"foot-col\">\n        <p class=\"foot-h\">The group</p>\n        <a href=\"#runs\">Terms of reference</a>\n        <a href=\"#legislation\">Legislation</a>\n      </div>\n      <div class=\"foot-col\">\n        <p class=\"foot-h\">Get involved</p>\n        <a href=\"mailto:hello@creativetechnorth.org.uk?subject=Founding%20supporter\">Become a supporter</a>\n        <a href=\"mailto:hello@creativetechnorth.org.uk?subject=Speaking%20or%20hosting\">Speak or host</a>\n        <a href=\"mailto:hello@creativetechnorth.org.uk\">Contact</a>\n      </div>\n    </div>\n    <div class=\"fine\">\n      <span>Independent, industry-led, not-for-profit. Across the North of England.</span>\n      <span>&copy; 2026 Creative Tech North</span>\n    </div>\n  </div>\n</footer>";var st=document.createElement('style');st.textContent=css;document.head.appendChild(st);document.body.innerHTML=html;document.title='Creative Tech North';
  document.documentElement.classList.add('js');
  document.body.classList.add('js');

  /* nav stays transparent over the hero, solidifies after it */
  (function(){
    var nav=document.getElementById('nav');
    var hero=document.querySelector('.hero');
    if(!hero||!('IntersectionObserver' in window)){nav.classList.add('solid');return;}
    new IntersectionObserver(function(e){
      nav.classList.toggle('solid',!e[0].isIntersecting);
    },{rootMargin:'-81px 0px 0px 0px',threshold:0}).observe(hero);
  })();

  /* reveal on enter */
  (function(){
    var els=document.querySelectorAll('.r');
    if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('in')});return;}
    var io=new IntersectionObserver(function(ents){
      ents.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target);}});
    },{rootMargin:'0px 0px -8% 0px',threshold:.08});
    els.forEach(function(e){io.observe(e)});
  })();

  /* scrollspy: mark the nav link for the section currently in view */
  (function(){
    if(!('IntersectionObserver' in window))return;
    var links=[].slice.call(document.querySelectorAll('.nav-links a[href^="#"]'));
    var map={};
    links.forEach(function(a){var id=a.getAttribute('href').slice(1);var s=document.getElementById(id);if(s)map[id]=a;});
    var ids=Object.keys(map);if(!ids.length)return;
    var io=new IntersectionObserver(function(ents){
      ents.forEach(function(en){
        if(en.isIntersecting){
          links.forEach(function(a){a.classList.remove('active');a.removeAttribute('aria-current');});
          var a=map[en.target.id];if(a){a.classList.add('active');a.setAttribute('aria-current','true');}
        }
      });
    },{rootMargin:'-45% 0px -50% 0px',threshold:0});
    ids.forEach(function(id){io.observe(document.getElementById(id));});
  })();

  /* hero video: desktop plays; mobile/small/reduced-motion drop it so the gradient shows and it stops loading */
  (function(){
    var v=document.querySelector('.hero-video');
    if(!v) return;
    var mm=window.matchMedia;
    var small=mm&&mm('(max-width:860px)').matches;
    var reduce=mm&&mm('(prefers-reduced-motion:reduce)').matches;
    if(small||reduce){ try{v.pause();}catch(e){} v.removeAttribute('autoplay'); v.remove(); }
  })();
})();